-- 프로토타입 위키(4장) → wiki_pages 일괄 이식. 한 번만 실행하세요(재실행 시 id 충돌 오류가 나면 이미 실행된 것).
insert into wiki_pages (id, user_id, section, title, definition, points, flagged)
select v.id, u.id, v.section, v.title, v.definition, v.points, v.flagged
from (values
  ('c5b626dc-6f05-5459-961f-12b6c758f82a'::uuid, '4장 · 1절 · 목공사 · 목재의분류와조직', '침엽수 · 활엽수', '침엽수(소나무·낙엽송·삼나무): 결이 곧고 가공 쉬움 — 구조재. 활엽수(참나무·단풍): 단단하고 무늬 좋음 — 가구·마감재.', '["비교·암기 — ''침엽수는 뼈대, 활엽수는 얼굴'' — 용도 한 줄 구분."]'::jsonb, false),
  ('84e58619-5d90-518a-8f77-fb64833eb328'::uuid, '4장 · 1절 · 목공사 · 목재의분류와조직', '심재 · 변재', '심재: 줄기 중심의 죽은 세포부 — 진하고 단단, 수축 적고 내구·방부성 우수. 변재: 바깥쪽 살아있는 부분 — 연하고 수분 많아 수축·부패 쉬움.', '["''좋은 목재는 심재'' — 심재율이 품질 지표."]'::jsonb, false),
  ('79390a55-f029-5635-a6f2-aa9d7ca728ea'::uuid, '4장 · 1절 · 목공사 · 목재의분류와조직', '나이테 · 춘재 · 추재', '나이테: 1년 성장 고리. 춘재(봄 성장, 연하고 넓음)+추재(여름~가을, 치밀하고 단단)가 한 쌍.', '["추재율이 높을수록(나이테가 촘촘할수록) 강도 큼."]'::jsonb, false),
  ('636c8139-430a-576a-b3ab-b48c543ce159'::uuid, '4장 · 1절 · 목공사 · 목재의분류와조직', '곧은결 · 널결', '곧은결(정목): 나이테에 직각으로 켠 면 — 평행 줄무늬, 수축 변형 적음. 널결(판목): 접선으로 켠 면 — 산 모양 무늬, 변형 큼.', '["비교·암기 — ''곧은결은 얌전하고 널결은 화려하지만 뒤틀린다''."]'::jsonb, false),
  ('99166adb-f4b6-5262-b1d6-e45c700d812a'::uuid, '4장 · 1절 · 목공사 · 함수율과건조', '목재 함수율', '목재 속 수분의 비율(전건 무게 기준).', '["구조재 사용 기준 대략 15~18% 이하, 마감·가구재는 더 낮게. ※기준 확인 — 함수율 관리가 목공 하자(수축·뒤틀림)의 근본."]'::jsonb, true),
  ('9c171107-9493-5639-bfc2-f8bdce6be376'::uuid, '4장 · 1절 · 목공사 · 함수율과건조', '섬유포화점', '세포 내 자유수는 다 빠지고 세포벽 결합수만 남은 상태(함수율 약 30%).', '["핵심 원리: 섬유포화점 이하로 건조될 때부터 수축·강도 증가 시작 — 그 이상에선 강도 변화 없음. 시험 최다 출제 개념."]'::jsonb, false),
  ('5c243426-4f80-5534-9017-7770c0abb573'::uuid, '4장 · 1절 · 목공사 · 함수율과건조', '자연건조', '야적·잔적하여 대기 중 건조. 비용 적고 품질 완만, 시간 오래 걸림(옥외 야적 규칙 — 지면 이격·잔적).', '[]'::jsonb, false),
  ('16333fc6-87cd-539d-bbc2-acda97f9372a'::uuid, '4장 · 1절 · 목공사 · 함수율과건조', '인공건조 (열기·진공)', '건조실에서 열기·제습·진공으로 단기간 건조. 빠르고 함수율 제어 정확 — 갈라짐 방지 위해 건조 스케줄 관리.', '["비교·암기 — 자연(느리고 순함) ↔ 인공(빠르고 정밀) — 고급재는 자연건조 후 인공 마무리도."]'::jsonb, false),
  ('b0e74de8-c8b2-5b02-be10-adbb20e71c61'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '옹이', '가지가 있던 자리. 산 옹이·죽은 옹이·빠진 옹이 — 강도 저하(특히 인장측)의 주 결함.', '[]'::jsonb, false),
  ('1c110ab8-0952-531d-93da-75ee86e1093a'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '갈라짐 (할렬)', '건조 수축 불균일로 갈라진 결함(윤할·심할·표면할).', '[]'::jsonb, false),
  ('7716b193-69e8-5012-b115-32511c9f3f0c'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '껍질박이', '수피(껍질)가 목질부 속에 말려 들어간 결함.', '[]'::jsonb, false),
  ('622a3da0-d2b3-5886-9cb3-edcbd1bf1d13'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '썩정이', '부패균에 의해 조직이 썩은 부분. 강도 상실 — 구조재 사용 불가.', '[]'::jsonb, false),
  ('6dd0dc34-de5f-52d4-8903-a4b090460891'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '뒤틀림 (목재)', '건조 불균일로 휘거나 비틀린 변형(활휨·굽음·비틀림·컵핑).', '[]'::jsonb, false),
  ('292962d7-95bb-5610-b7ca-413062f8e911'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '방부처리 (가압주입·도포·침지)', '부패균·습기로부터 보호하는 처리. 가압주입(약액을 압력으로 깊이 — 가장 확실), 침지, 도포(표면만) 순의 효과.', '["사용 환경 등급(지면 접촉 여부 등)에 따라 처리 수준 규정. ※확인."]'::jsonb, true),
  ('32d68f28-eebe-5e28-a668-9d9f352ee102'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '방충처리', '흰개미·벌레 피해 방지 약제 처리. 방부와 병행.', '[]'::jsonb, false),
  ('ab4e4863-0599-59e0-b597-241d3ab780b5'::uuid, '4장 · 1절 · 목공사 · 목재의결함과보존', '난연처리 (목재)', '난연 약제 주입·도포로 착화·연소 확산을 늦추는 처리. 목재 내장재 규제 대응.', '[]'::jsonb, false),
  ('82368003-e9c9-5140-85b1-a775509f308d'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', '합판', '단판(베니어)을 결 방향을 직교시켜 홀수 겹 접착한 판.', '["직교 적층으로 수축·강도의 방향성 제거 — ''나무의 약점(이방성)을 겹쳐서 지운다''가 공학목재 전체의 원리."]'::jsonb, false),
  ('a7afc4ec-892f-5291-a6bf-8f77b572de03'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', '집성재 (글루램)', '제재목 층재를 섬유 방향을 나란히 적층 접착한 구조 부재. 대단면·장스팬·곡선 부재 가능, 결함 분산으로 품질 균일.', '[]'::jsonb, false),
  ('d0836eb3-6de9-57e2-9b34-5b015cbd9afc'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', 'LVL', '단판(베니어)을 섬유 방향 나란히 적층한 구조재. 집성재보다 얇은 층 — 보·헤더용.', '[]'::jsonb, false),
  ('648951f7-df3f-568d-b8cf-a78e7cb56093'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', 'CLT (구조용 집성판)', '층재를 직교로 적층 접착한 대형 패널. 벽·바닥판 자체를 목재로 — 목조 고층화(매스팀버)의 핵심 재료.', '["비교·암기 — 집성재·LVL(결 나란히=보·기둥) ↔ 합판·CLT(결 직교=판재) — ''나란히는 막대, 직교는 판''."]'::jsonb, false),
  ('27620f56-9666-59f5-bb9d-dbff40f1db3e'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', '파티클보드 (PB)', '목재 조각(파티클)+접착제 열압 성형판. 저렴 — 가구 몸통, 습기에 약함.', '["비교·암기 — PB(작은 조각) - MDF(섬유) - OSB(큰 조각·배향) — 원료 크기로 구분."]'::jsonb, false),
  ('7c86ffdd-56c4-5d98-8376-eec6b32ba2e1'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', 'MDF', '목섬유+접착제 성형판. 면이 곱고 가공성 최고 — 몰딩·도장 바탕, 습기·나사 유지력 약함.', '[]'::jsonb, false),
  ('0073de24-6735-505b-8d5d-d122b52fc739'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', 'OSB', '큰 목편(스트랜드)을 배향 적층한 판. 구조용 덮개(경골목구조 벽·지붕 바탕).', '[]'::jsonb, false),
  ('858a4aeb-b19f-5427-830d-48a439a9163f'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', '플로어링', '바닥판용 쪽매 가공(제혀쪽매) 목재 판재의 총칭.', '[]'::jsonb, false),
  ('4f3d96e7-e161-5301-bbc0-511b822c145d'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', '무늬목', '고급 수종을 얇게 켠 장식 단판. 바탕판에 붙여 고급 수종 외관 구현.', '[]'::jsonb, false),
  ('f1adf3e9-adb2-5764-ba69-471895c28d85'::uuid, '4장 · 1절 · 목공사 · 가공목질재료공학목재', '코펜하겐리브', '단면이 리브(골) 형태인 목재 벽 마감재. 음향 조절(강당·극장 벽) 겸 장식.', '[]'::jsonb, false),
  ('18c8e91f-3e6e-5c06-b013-dd9baaca62e6'::uuid, '4장 · 1절 · 목공사 · 목재의접합', '마름질 · 바심질', '마름질: 치수대로 자르는 일. 바심질: 이음·맞춤 자리를 파고 다듬는 일.', '[]'::jsonb, false),
  ('a5977457-e1bf-5ae6-8fa1-8f73ca476ab4'::uuid, '4장 · 1절 · 목공사 · 목재의접합', '이음 · 맞춤 · 쪽매', '이음: 길이 방향으로 잇기. 맞춤: 각도를 이뤄 짜기. 쪽매: 판재를 옆으로 붙이기(제혀·반턱·틈막이대쪽매 등).', '["비교·암기 — ''길이는 이음, 각도는 맞춤, 옆은 쪽매'' — 방향으로 구분."]'::jsonb, false),
  ('9ae4c4d2-a46d-525a-9cc3-f0754495d6b5'::uuid, '4장 · 1절 · 목공사 · 목재의접합', '장부맞춤', '장부(촉)를 내어 구멍에 끼우는 대표 맞춤.', '[]'::jsonb, false),
  ('acf6a036-09cc-5abf-b5be-916055307eaa'::uuid, '4장 · 1절 · 목공사 · 목재의접합', '주먹장', '주먹(사다리꼴) 모양 장부로 빠지지 않게 맞추는 이음·맞춤(더브테일).', '[]'::jsonb, false),
  ('5cd0816f-d2dd-5edd-947d-e3ad716f1fa9'::uuid, '4장 · 1절 · 목공사 · 목재의접합', '촉', '두 부재를 맞출 때 박는 나무·금속 핀.', '[]'::jsonb, false),
  ('c755d3c8-6e11-592d-a9b3-f69482073180'::uuid, '4장 · 1절 · 목공사 · 목재의접합', '목재 접합철물', '볼트·듀벨·꺾쇠·감잡이쇠·주걱볼트 등 목구조 접합 보강 철물. 현대 목구조는 철물 접합이 표준.', '[]'::jsonb, false),
  ('59ea1e6d-c917-5476-896e-c6389db669c9'::uuid, '4장 · 2절 · 타일공사 · 타일의종류', '도기질타일', '낮은 온도 소성(약 1000도급 ※확인), 흡수율 큼(18% 이하) — 흡수·동해 우려로 내장 전용(벽).', '["''도기는 물 먹는 실내용'' — 외부·바닥 사용 불가가 정답 포인트."]'::jsonb, true),
  ('40b8b4ed-08fa-5a43-99b1-a3003a206293'::uuid, '4장 · 2절 · 타일공사 · 타일의종류', '석기질타일', '중간 소성. 흡수율 중간(5% 이하) — 바닥·외부 가능.', '[]'::jsonb, false),
  ('0c909bc0-aae1-59f7-9c16-c757a975d6a1'::uuid, '4장 · 2절 · 타일공사 · 타일의종류', '자기질타일', '고온 소성(1250도급 ※확인), 흡수율 최소(1% 이하), 강도 최고 — 바닥·외장 표준(포세린).', '["비교·암기 — 소성온도 높을수록: 흡수율 낮고 단단 — 도기(내장 벽) < 석기 < 자기(바닥·외장), 흡수율 숫자 3-5-1 대비로 암기. ※확인."]'::jsonb, true),
  ('650e1224-24d8-5cf2-9dcf-5b73e34a4276'::uuid, '4장 · 2절 · 타일공사 · 타일의종류', '소성온도와 흡수율', '타일 분류의 두 축. 소성온도가 높을수록 조직이 치밀해져 흡수율이 낮아짐 — 용도(내·외·바닥)를 결정.', '[]'::jsonb, false),
  ('2b369c41-a61e-5569-bbeb-0dffa5fd2123'::uuid, '4장 · 2절 · 타일공사 · 타일의종류', '시유 · 무유 타일', '유약을 입힌 타일(시유)과 소지 그대로(무유). 무유는 마모에 강해 바닥에 유리.', '[]'::jsonb, false),
  ('1d2e5ca7-ee6b-5738-8d9a-59f8beb54e71'::uuid, '4장 · 2절 · 타일공사 · 타일의종류', '모자이크타일', '소형 타일을 종이·망에 붙여 유닛화한 제품. 곡면·욕실 바닥.', '[]'::jsonb, false),
  ('ba0f896d-493c-502c-80ec-481c0d003722'::uuid, '4장 · 2절 · 타일공사 · 붙임공법5대방식', '떠붙임공법', '타일 뒷면에 모르타르를 떠서 벽에 눌러 붙이는 재래 공법.', '["뒷채움 부족(공극)이 생기기 쉬움 — 박리·백화·동해의 원인, 숙련 의존."]'::jsonb, false),
  ('22f14638-58ae-52a0-b8ec-114d68d9f2b5'::uuid, '4장 · 2절 · 타일공사 · 붙임공법5대방식', '압착공법', '바탕에 모르타르를 바르고 타일을 눌러 붙이는 공법.', '["오픈타임 초과가 최대 리스크 — 표면이 마른 모르타르에 붙이면 부착력 급감."]'::jsonb, false),
  ('53e66af3-ac11-5aba-97a7-6f737fbda0a3'::uuid, '4장 · 2절 · 타일공사 · 붙임공법5대방식', '개량압착공법', '바탕과 타일 뒷면 양쪽에 모르타르를 발라 붙이는 공법. 부착 신뢰도 향상 — 외벽 타일의 표준.', '["비교·암기 — 떠붙임(타일에만) - 압착(바탕에만) - 개량압착(양쪽 다) — 모르타르를 어디에 바르냐로 구분."]'::jsonb, false),
  ('08d6b8e8-7e7c-54de-a1ac-861ac26b2694'::uuid, '4장 · 2절 · 타일공사 · 붙임공법5대방식', '접착제붙임공법 (유기질)', '유기질 접착제로 붙이는 내장 공법. 얇은 바름·빠른 시공 — 물 닿는 곳·외부 부적합.', '[]'::jsonb, false),
  ('5aa2b5f4-7668-5e03-9585-a41fbd709596'::uuid, '4장 · 2절 · 타일공사 · 붙임공법5대방식', '동시줄눈공법 (밀착)', '진동기로 타일을 눌러 붙이며 모르타르가 줄눈으로 솟아오르게 해 줄눈까지 동시에 만드는 외벽 공법.', '[]'::jsonb, false),
  ('7a62b395-1fb0-598e-9be1-0caadc040e76'::uuid, '4장 · 2절 · 타일공사 · 시공관리', '타일나누기도', '타일 장수·줄눈 폭·조각(커팅) 위치를 미리 계획하는 도면. 개구부·모서리에서 반 토막 이하 조각이 안 나오게.', '[]'::jsonb, false),
  ('e1974e75-a4a1-58cf-92a7-64c517fd6e30'::uuid, '4장 · 2절 · 타일공사 · 시공관리', '타일 줄눈', '타일 사이 충전 줄눈. 치수 오차 흡수+부착·거동 여유. 줄눈 폭 표준 ※확인.', '[]'::jsonb, true),
  ('d3618ed8-638e-5531-93a5-d1380645e6cc'::uuid, '4장 · 2절 · 타일공사 · 시공관리', '신축줄눈 (타일)', '일정 간격(수 m마다 ※확인)과 이질 바탕 경계에 두는 탄성 줄눈. 바탕 거동이 타일을 밀어 올리지 않게 분리.', '["신축줄눈 생략이 대면적 타일 박리·솟음(폭렬적 들뜸)의 단골 원인."]'::jsonb, true),
  ('8ebfc362-f641-585d-94cf-efa47079f809'::uuid, '4장 · 2절 · 타일공사 · 시공관리', '오픈타임', '모르타르·접착제를 바른 후 타일을 붙일 수 있는 한계 시간.', '["초과하면 표면 경화로 부착력 급감 — 압착계 공법 하자의 1순위 원인. ※시간 확인."]'::jsonb, true),
  ('103f7e36-92aa-5355-8c40-63d3ac2f767e'::uuid, '4장 · 2절 · 타일공사 · 타일하자와검사', '타일 박리 · 박락', '타일이 바탕에서 떨어지는 하자(박리=들뜸, 박락=탈락).', '["원인: 오픈타임 초과, 뒷채움 부족, 바탕 거동(신축줄눈 없음), 동해. 외벽 박락은 인명 사고 — 안전 이슈."]'::jsonb, false),
  ('65949618-e6c6-55aa-9f17-9b727a577200'::uuid, '4장 · 2절 · 타일공사 · 타일하자와검사', '백화 (타일)', '줄눈·뒷채움의 가용 성분이 표면으로 나와 흰 얼룩. 물 침투 경로 차단이 근본 대책.', '[]'::jsonb, false),
  ('e110b2be-8be3-5394-a865-c4a9b84e591d'::uuid, '4장 · 2절 · 타일공사 · 타일하자와검사', '부착강도시험 (인발)', '접착 후 타일에 지그를 붙여 당겨 떼는 힘을 측정. 기준값 이상 확인. ※값·빈도 확인.', '[]'::jsonb, true),
  ('7d024fdc-715e-59e4-bc02-a882f4668cfb'::uuid, '4장 · 2절 · 타일공사 · 타일하자와검사', '두들김검사', '검사봉으로 두들겨 소리로 들뜸(공극)을 찾는 전수 검사. 타설·부착 후 일정 기간 뒤 실시.', '[]'::jsonb, false),
  ('1ea5f5d2-5bd2-5644-8873-acc93334b205'::uuid, '4장 · 2절 · 타일공사 · 타일하자와검사', '타일 뒷굽 (뒷발)', '타일 뒷면의 요철. 모르타르 물림을 만들어 부착력 확보 — 외장 타일은 뒷굽 형상 규정. ※확인.', '[]'::jsonb, true),
  ('8fbb5c05-bb1e-5148-93b9-d0b0b302ba34'::uuid, '4장 · 3절 · 미장공사 · 재료의분류굳는원리', '기경성 미장재료', '공기 중 이산화탄소와 반응해 굳는 재료 — 회반죽, 돌로마이트플라스터, 흙, 소석회.', '["물속·습한 곳에서는 안 굳음. 경화 느리고 수축 큼(여물로 균열 분산)."]'::jsonb, false),
  ('414b30c5-eb2d-5ce4-bcbf-0207c95457d9'::uuid, '4장 · 3절 · 미장공사 · 재료의분류굳는원리', '수경성 미장재료', '물과 반응해(수화) 굳는 재료 — 시멘트모르타르, 석고플라스터.', '["비교·암기 — 기경성(공기로 굳음: 회·돌로마이트·흙) ↔ 수경성(물로 굳음: 시멘트·석고) — 미장 시험의 제1 분류. ''석고는 수경성''이 함정 단골."]'::jsonb, false),
  ('313113df-56b2-5018-b4a9-bf82c70577f3'::uuid, '4장 · 3절 · 미장공사 · 재료의분류굳는원리', '시멘트모르타르', '시멘트+모래+물. 미장의 표준 재료 — 내·외부, 바탕·마감 겸용.', '[]'::jsonb, false),
  ('cb319e41-6211-55b6-a68d-c03893bf0ec6'::uuid, '4장 · 3절 · 미장공사 · 재료의분류굳는원리', '미장 배합비', '용도별 시멘트:모래 비율(초벌 1:3, 정벌 1:2 등 관용 ※확인).', '["부배합(시멘트 많음)은 강하지만 수축 균열 큼, 빈배합은 반대 — 초벌은 부배합, 갈수록 빈배합이 원칙."]'::jsonb, true),
  ('357fe031-ab02-5847-a951-299b0a1d0ecd'::uuid, '4장 · 3절 · 미장공사 · 재료의분류굳는원리', '초벌 · 재벌 · 정벌', '3회 나눠 바르는 표준 공정. 초벌(부착·바탕 잡기) - 재벌(평활) - 정벌(마감).', '["각 층은 충분히 건조·경화 후 다음 층 — 한 번에 두껍게 바르면 처짐·균열. 1회 바름두께 한도 ※확인."]'::jsonb, true),
  ('3d0fedd6-830d-5d44-9f37-aca8fac5a9c2'::uuid, '4장 · 3절 · 미장공사 · 재료의분류굳는원리', '바탕처리', '미장 전 바탕 청소·물축임·요철 조정·흡수 조정(시멘트풀). 부착의 절반은 바탕에서 결정.', '["콘크리트 바탕이 너무 매끈하면 부착 불리 — 거칠게(치핑)·접착증강제."]'::jsonb, false),
  ('0878bf4f-44d9-5f7a-a817-ca12e0962fc9'::uuid, '4장 · 3절 · 미장공사 · 보강부속재료', '라스 (메탈 · 와이어)', '미장 물림용 철망(메탈라스=강판 절개, 와이어라스=철선). 목조 바탕·이질재 접합부의 균열 방지 보강.', '[]'::jsonb, false),
  ('e5fec8f6-d022-55e0-8168-6d55cd5ddcdd'::uuid, '4장 · 3절 · 미장공사 · 보강부속재료', '코너비드', '기둥·벽 모서리에 대는 보호 철물. 모서리 파손 방지+미장 규준 역할.', '[]'::jsonb, false),
  ('4eec7fa7-b232-5ab2-88d5-7737028a680b'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '회반죽', '소석회+모래+여물+해초풀을 섞어 바르는 전통 기경성 미장.', '["여물(균열 분산)·해초풀(부착·보수성)의 역할 문제가 단골."]'::jsonb, false),
  ('53e34e0d-3dd3-5bd7-aa5d-860da8deab43'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '여물 · 해초풀', '여물: 짚·삼 섬유 — 수축 균열을 잘게 분산. 해초풀: 해초 끓인 풀 — 접착력·보수성(마르지 않게).', '[]'::jsonb, false),
  ('1ee4b6bd-3a62-507d-95ea-ca5f4c8ff95d'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '돌로마이트플라스터', '돌로마이트 석회 미장. 점성이 커 여물 없이 시공(회반죽과 차이), 기경성 — 수축 커서 여물 필요.', '["비교·암기 — 회반죽(해초풀 필요) ↔ 돌로마이트(자체 점성, 풀 불필요) — 풀의 유무로 구분."]'::jsonb, false),
  ('89e61450-2d3b-54f8-b79b-9a4a5062928f'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '석고플라스터', '석고계 수경성 미장. 경화 빠르고 수축 거의 없음(팽창성) — 균열 적고 마감 곱다. 물에 약함(내부 전용).', '["비교·암기 — 석고(수경성·무수축·빠름·물에 약함) ↔ 회석회(기경성·수축·느림) — 성질이 정반대인 짝."]'::jsonb, false),
  ('c2e21a62-6993-5070-9540-29de3045f360'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '킨즈시멘트 (경석고 플라스터)', '무수석고에 경화 촉진제를 넣은 고강도 석고 미장. 경도 높고 광택 마감 — 바닥·벽 고급 마감.', '[]'::jsonb, false),
  ('2a088122-c4d5-53ac-a7c0-8f6d23d61f90'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '흙바름', '진흙+모래+짚여물의 전통 기경성 미장. 친환경·조습 — 한식·친환경 건축 재조명.', '[]'::jsonb, false),
  ('f18e481d-55f0-58cf-a9f6-4fb3e2301800'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '인조석바름', '종석+백시멘트+안료를 바르고 씻어내기·갈기·잔다듬으로 마감해 천연석 질감을 내는 미장.', '[]'::jsonb, false),
  ('d6698813-721a-5114-9a03-6aa1525d4972'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '테라조 현장갈기', '대리석 종석 모르타르를 현장 타설 후 연마. 줄눈대(황동)로 구획 — 균열 유도+문양.', '[]'::jsonb, false),
  ('88fd34ea-169c-5ef4-94c3-5861abbc9466'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '리신바름', '석회+종석 반죽을 바르고 굳기 전 긁어내 거친 질감을 내는 마감(스크래치).', '[]'::jsonb, false),
  ('d153cb8f-81ef-5a68-bcab-8c99026615dd'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '러프코트', '모르타르·플라스터를 뿜칠·흩뿌려 거친 표면을 만드는 마감.', '[]'::jsonb, false),
  ('89ecda70-1820-5f3d-a84b-b4375c3a4a74'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '셀프레벨링재', '물처럼 흘러 스스로 수평을 잡는 바닥 마감재(석고계·시멘트계).', '["미장공 기능 의존을 줄인 재료 — 시공 중 통풍(바람) 금지: 표면 주름 방지."]'::jsonb, false),
  ('81ac2794-a847-5fe6-851d-2a4dff241bef'::uuid, '4장 · 3절 · 미장공사 · 재료별미장', '단열모르타르', '경량 골재(펄라이트 등) 혼입 단열 성능 모르타르. 열교 부위 보조 단열.', '[]'::jsonb, false),
  ('381e8c74-e60f-55aa-9f21-e08d42687b56'::uuid, '4장 · 3절 · 미장공사 · 미장하자', '미장 균열 · 들뜸', '원인: 배합 과다(부배합), 두껍게 1회 바름, 바탕 처리 불량, 급격 건조, 바탕 거동.', '["대책: 배합·두께 준수, 층별 건조, 라스 보강, 신축줄눈 — ''미장 하자는 대부분 서두름에서 온다''."]'::jsonb, false),
  ('2c564ef4-1eb9-536d-842e-b8b45b15a469'::uuid, '4장 · 3절 · 미장공사 · 미장하자', '미장 백화', '재료 중 가용 석회분이 표면 석출. 물·수분 관리 문제와 동일 계열.', '[]'::jsonb, false),
  ('d3052efd-fd36-5b30-addc-8a71885e2ada'::uuid, '4장 · 3절 · 미장공사 · 미장하자', '1회 바름두께', '한 번에 바를 수 있는 두께 한도(부위별 6~9mm 관용 ※확인). 초과 시 처짐·박리.', '[]'::jsonb, true),
  ('77999610-59fd-576b-8ec2-fd59b89fccfd'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '유성페인트', '건성유+안료 도료. 부착·내후성 양호, 건조 느림·알칼리에 약함 — 콘크리트·모르타르 직접 도장 불가(비누화).', '["''유성은 알칼리에 약하다'' — 콘크리트 바탕엔 바탕 중화·전용 프라이머가 정답 포인트."]'::jsonb, false),
  ('76b5d013-1187-54ed-839a-c569624318e5'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '수성페인트', '물이 용제인 도료. 냄새 적고 알칼리 강함 — 콘크리트·모르타르 내외부 표준.', '[]'::jsonb, false),
  ('40694b9c-f34c-586f-afd6-4057d3e5e066'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '에멀션페인트', '수지를 물에 유화시킨 수성 도료(현대 수성의 주류). 내수성 보유.', '[]'::jsonb, false),
  ('32df474d-fccc-5e0d-93b6-a0bcbaa4b839'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '조합페인트', '현장에서 바로 쓰도록 조합된 유성계 도료. 철부·목부 범용.', '[]'::jsonb, false),
  ('29094675-4cf8-5412-a1ba-eae6352c0221'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '바니시 (니스)', '수지+용제의 투명 도료. 목부 투명 마감(나뭇결 살림).', '[]'::jsonb, false),
  ('44a1a31e-f5e7-5c39-96ae-ede6d1b4e87e'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '래커', '질화면(NC) 수지 속건 도료. 건조 매우 빠름 — 뿜칠 시공, 목부·금속 마감. 두꺼운 도막 불가(여러 번 얇게).', '[]'::jsonb, false),
  ('03cbccb1-9dc4-5333-b6da-ac214e753da4'::uuid, '4장 · 4절 · 도장공사 · 도료의종류', '에나멜', '유성 바니시+안료의 유색 광택 도료. 도막 단단하고 광택 — 철부·목부.', '[]'::jsonb, false),
  ('0b179734-7031-5ca1-8544-94db2ee976fc'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '방청도료', '철부 녹 방지 초벌 도료의 총칭. 광명단·징크리치·에폭시계 등.', '[]'::jsonb, false),
  ('aff0824a-72b6-58f8-9f19-9e6d95368f62'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '광명단', '연단(납계) 방청 초벌 도료 — 전통적 대표(납 규제로 대체 확산 ※확인).', '[]'::jsonb, true),
  ('d35e93fd-fb5d-5d37-a988-cf50f56a0a23'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '징크리치 프라이머', '아연말 고함량 방청 도료. 아연의 희생방식 원리 — 중방식 도장의 표준 초벌.', '[]'::jsonb, false),
  ('ac7ec3e7-8d81-5d85-85c9-d10adc2c26e8'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '에폭시도료', '에폭시 수지 도료. 부착·내약품·내수 최강 — 바닥 마감·중방식 초중도.', '["약점: 자외선에 황변·초킹 — 외부 상도로는 부적합(상도는 우레탄·불소)."]'::jsonb, false),
  ('ae813dc0-1c8c-5a9e-8ea9-618256baa810'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '우레탄도료', '폴리우레탄 도료. 탄성·내후·광택 — 외부 상도·바닥 탄성 마감.', '[]'::jsonb, false),
  ('00bb646e-c84d-5949-9388-004dce94d6c5'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '불소수지도료', '최고 내후성 도료. 초고층 외장·금속 패널 — 고가.', '["비교·암기 — 중방식 도장 3층 논리: 방청(징크) - 중도(에폭시) - 상도(우레탄·불소, 자외선 방패). ''에폭시는 속에, 우레탄은 겉에''."]'::jsonb, false),
  ('fe995d1f-5ca5-5019-a1d7-43585482c2d4'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '다채무늬도료', '한 번 뿜칠로 여러 색 무늬가 나오는 도료. 내부 벽 마감.', '[]'::jsonb, false),
  ('5ebee95f-4284-5dc0-8026-dbb82c290527'::uuid, '4장 · 4절 · 도장공사 · 기능성도료', '본타일', '모르타르·수지계를 뿜칠해 요철 무늬를 만들고 도장하는 외벽 마감. 균열 은폐·질감.', '[]'::jsonb, false),
  ('ecda3766-ac3d-53b6-9889-7313e8bbb982'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '프라이머 (도장)', '바탕과 도료의 접착·차단(흡수 조정, 녹 방지)을 담당하는 초벌 도료. ''도장의 기초공사''.', '[]'::jsonb, false),
  ('e91ccb9e-2722-54c2-af0f-40df35aae0c5'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '퍼티 · 샌딩', '퍼티: 구멍·요철을 메우는 충전재. 샌딩: 연마지로 갈아 평활하게 — 퍼티·샌딩 반복이 면 품질을 결정.', '[]'::jsonb, false),
  ('58c17f3a-6212-51d4-8ce9-99e425c6cafc'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '붓칠 · 롤러칠', '소면적·구석(붓), 넓은 면(롤러). 이음자국·롤러 자국 관리.', '[]'::jsonb, false),
  ('ce391e53-27fd-5c4e-b69d-4e4e88185110'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '뿜칠 (에어스프레이)', '압축공기로 도료를 안개화해 분사. 균일·빠름 — 비산(오버스프레이) 보양 필수.', '[]'::jsonb, false),
  ('37eb96db-d5b9-54a2-8188-6a64d982fdcf'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '에어리스스프레이', '도료 자체를 고압으로 분사(공기 미사용). 고점도·후막 시공 — 대면적 표준.', '[]'::jsonb, false),
  ('bb0fbef5-a9e5-5c8e-bf50-4bbed06af2a5'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '도막두께 관리', '규정 도막두께(건조도막 기준) 확보 확인 — 방청·내화 도료는 두께가 곧 성능. 측정기 검사. ※기준 확인.', '[]'::jsonb, true),
  ('7a3fc3f4-b9b2-5339-adbf-913206c339f6'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '가사시간 (포트라이프)', '2액형 도료(에폭시·우레탄)를 혼합 후 사용할 수 있는 한계 시간. 초과분은 폐기.', '["비교·암기 — 오픈타임(발라 놓고 붙일 수 있는 시간 — 접착)과 가사시간(섞어 놓고 쓸 수 있는 시간 — 도료·수지)을 구분."]'::jsonb, false),
  ('e3458874-c6d4-5709-a6fa-d622294676b8'::uuid, '4장 · 4절 · 도장공사 · 도장공정', '희석제 (신너)', '도료 점도 조절 용제. 도료별 전용 신너 사용 — 화기·환기·보관(인화성) 안전관리 대상.', '[]'::jsonb, false),
  ('fc0b5ad2-2c6f-54a3-94ed-f130a4722d05'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '흘림 (새깅)', '수직면에서 도료가 흘러내린 자국. 두껍게 칠함·점도 낮음이 원인.', '[]'::jsonb, false),
  ('45b4b611-3b45-5ae8-9380-0453d50611b5'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '백화 (블러싱)', '속건 도료(래커) 시공 시 표면 온도 저하로 수분이 응축해 하얗게 흐려짐. 고온다습한 날 발생 — 지연 신너로 대응.', '[]'::jsonb, false),
  ('44563713-fba7-5126-8a19-5127ec78f586'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '부풀음 (블리스터)', '도막 아래 수분·용제가 기화해 부푸는 결함. 바탕 수분(함수율) 과다가 주원인 — ''바탕이 마르기 전에 칠하지 마라''.', '[]'::jsonb, false),
  ('332bcbd5-c5f2-5bb8-9b63-d7955a090abd'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '핀홀', '도막에 바늘구멍. 바탕 기포·용제 급증발이 원인.', '[]'::jsonb, false),
  ('b51ba25d-f94d-51f4-85b4-f9564355b5d4'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '오렌지필', '귤껍질 같은 요철 표면. 뿜칠 점도·거리 부적정.', '[]'::jsonb, false),
  ('e3f82a86-43bf-563e-8440-0c59570092ea'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '번짐 (블리딩)', '하도의 색·성분이 상도로 배어 나옴. 이색 도료 간 차단(실러) 미비.', '[]'::jsonb, false),
  ('34774fa1-d0bb-57b8-a8b3-22a18f563a9d'::uuid, '4장 · 4절 · 도장공사 · 도장결함원인별', '도장 균열 (체킹 · 크래킹)', '도막 표면·깊이 균열. 두꺼운 도막·건조 불충분 층 위 재도장이 원인.', '["비교·암기 — 도장 결함의 공통 뿌리 셋: 바탕 수분, 두께 과다, 건조 시간 미준수 — 결함 이름이 달라도 원인은 이 셋으로 수렴."]'::jsonb, false),
  ('44e45b19-24cb-59c6-aff9-9870382e4525'::uuid, '4장 · 5절 · 수장공사기타마감 · 천장', '경량철골천장틀', '경량 형강으로 천장 하지를 짜고 판재를 붙이는 건식 천장의 표준 시스템.', '["구성 하중 흐름: 슬래브 - 인서트·앵커 - 달대(행거볼트) - 캐링채널 - M바 - 천장판."]'::jsonb, false),
  ('124e7aa9-a9cb-5700-a156-eb3e36ae84cf'::uuid, '4장 · 5절 · 수장공사기타마감 · 천장', 'M바 · T바 · 캐링채널', '캐링채널: 주 지지 부재(상부). M바: 판을 직접 받는 하부 바(석고보드용). T바: 텍스를 얹는 노출 격자 바.', '["비교·암기 — ''T바는 얹는 천장(텍스), M바는 붙이는 천장(석고보드)'' — 마감재로 구분."]'::jsonb, false),
  ('2cb65768-6c25-5b68-bb52-413e8b456f90'::uuid, '4장 · 5절 · 수장공사기타마감 · 천장', '달대 · 행거', '천장틀을 슬래브에 매다는 수직재(달대볼트)와 조절 철물(행거). 내진 천장에서는 흔들림 방지 보강 추가.', '[]'::jsonb, false),
  ('915d5d26-dcae-5220-93e6-763d91d92139'::uuid, '4장 · 5절 · 수장공사기타마감 · 천장', '텍스 · 마이너스몰딩', '텍스: 흡음 천장판(암면 흡음판). 마이너스몰딩: 벽·천장 접합부를 띄워 홈으로 처리하는 디테일.', '[]'::jsonb, false),
  ('85890e24-386a-5c9a-92f1-22c7a36a61f9'::uuid, '4장 · 5절 · 수장공사기타마감 · 천장', '석고보드', '석고 심재+종이 피복 판재. 방화(결정수의 흡열)·차음·경제성 — 벽·천장 건식 마감의 표준.', '["방수·방화·차음 등 기능별 제품 구분. 못 유지력 약함 — 하지 위치에 고정."]'::jsonb, false),
  ('72e18677-b296-55c8-a3c2-78cc960517e4'::uuid, '4장 · 5절 · 수장공사기타마감 · 천장', '시멘트판 (CRC)', '시멘트+섬유 보강판. 물에 강함 — 욕실 등 습한 곳의 석고보드 대체 하지.', '[]'::jsonb, false),
  ('9a39d589-83a9-5e85-956e-1c5c2649afb6'::uuid, '4장 · 5절 · 수장공사기타마감 · 벽도배', '도배 (초배 · 정배)', '초배: 바탕 고르기용 밑종이(부직포·운용지). 정배: 마감 벽지 바름.', '["뜨움 시공(봉투바름): 바탕 요철·균열을 감추기 위해 가장자리만 붙임."]'::jsonb, false),
  ('c374f1c2-d10e-5c69-8d3a-96916dce1dd2'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '원목마루', '통원목 판재 마루. 질감 최고, 수축팽창·가격 부담.', '[]'::jsonb, false),
  ('41dc4984-363a-518c-8912-1eb073befae2'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '합판(엔지니어드)마루', '합판 위 무늬목 표면층. 치수 안정 — 온돌 접착 시공.', '[]'::jsonb, false),
  ('42a6c76e-ca44-51c3-a10b-70cab5580348'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '강화마루', 'HDF 심재+표면 라미네이트. 내마모 최고, 클릭 결합 현가(띄움) 시공 — 접착제 불사용.', '[]'::jsonb, false),
  ('bddc97d8-03c0-5f90-ad8e-514a9184a774'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '강마루', '합판 심재+표면 강화 필름의 절충형. 온돌 접착 시공+내마모 — 국내 아파트 주류.', '["비교·암기 — 마루 4형제: 원목(질감) / 합판(안정) / 강화(내마모·띄움) / 강마루(절충·접착) — 심재와 시공법으로 구분."]'::jsonb, false),
  ('9ecb0232-a880-5f5d-b754-d8716f9aa303'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '온돌마루', '바닥 난방(온돌) 대응 마루의 통칭. 열·건조 수축에 견디는 치수 안정성이 요건.', '[]'::jsonb, false),
  ('ec5adef7-a04a-5a41-81b0-4daaf69d7890'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '액세스플로어 (OA플로어)', '바닥을 이중으로 띄워 배선 공간을 확보한 패널 바닥. 사무실·전산실 표준.', '[]'::jsonb, false),
  ('c6977fe9-68fa-5cd6-be26-29e344da6756'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '타일카펫', '정사각 카펫 타일. 부분 교체·배선 접근 용이 — 사무 공간.', '[]'::jsonb, false),
  ('473842e0-ea3c-5850-8e9e-2f29ca27d864'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '데코타일', 'PVC 사각 타일 바닥재. 내구·디자인 — 상업 공간.', '[]'::jsonb, false),
  ('2114cc85-9c26-5e83-987c-41eddba0bf07'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', 'PVC 바닥재 (륨)', '롤형 PVC 시트 바닥(모노륨 등). 주거·병원 — 이음 용접(심리스)로 위생 확보.', '[]'::jsonb, false),
  ('681aaa28-b021-55cb-a3c9-952e40b94532'::uuid, '4장 · 5절 · 수장공사기타마감 · 바닥재', '에폭시 바닥마감', '에폭시 수지 코팅·라이닝 바닥. 무진·내약품 — 주차장·공장·병원.', '[]'::jsonb, false),
  ('73e745e3-1b5a-5031-8814-34a90a6e6f0e'::uuid, '4장 · 5절 · 수장공사기타마감 · 걸레받이칸막이문', '걸레받이', '벽 하부 보호·마감재(바닥과 벽의 접점). 청소 시 벽 오염 방지.', '[]'::jsonb, false),
  ('44741802-492b-5a7f-a682-2d2436cf7ab9'::uuid, '4장 · 5절 · 수장공사기타마감 · 걸레받이칸막이문', '몰딩 · 코너가드', '몰딩: 재료 접합부·모서리를 덮는 마감 부재(천장 몰딩 등). 코너가드: 모서리 파손 보호재.', '[]'::jsonb, false),
  ('72619643-88b1-5771-9b75-681277b2993a'::uuid, '4장 · 5절 · 수장공사기타마감 · 걸레받이칸막이문', '경량칸막이 (스터드 · 런너)', '런너(상하 수평 틀)+스터드(수직 샛기둥)에 석고보드를 양면 부착하는 건식 벽.', '["속에 글라스울 충전(차음)+설비 배관 통과 — 습식 조적을 대체한 현대 칸막이 표준."]'::jsonb, false),
  ('aaabd31d-ea19-5c68-8287-56e2fa8fe538'::uuid, '4장 · 5절 · 수장공사기타마감 · 걸레받이칸막이문', '방화문', '화재 확산을 막는 성능 인정 문(60분+, 60분, 30분 등급 ※확인).', '["상시 닫힘(도어클로저)+자동 폐쇄 장치 — ''열어두면 방화문이 아니다''. 성능 시험·품질 인증제 강화 흐름."]'::jsonb, true),
  ('90a80b50-172e-56d6-8370-abc00763bf72'::uuid, '4장 · 5절 · 수장공사기타마감 · 걸레받이칸막이문', '방화구획', '건물 내부를 내화구조 벽·바닥·방화문·방화셔터로 구획해 화재 확산을 차단하는 것. 면적·층·용도별 구획 기준. ※확인.', '["구획 관통부(배관·덕트) 틈새 내화충전이 실무 취약점 — 안전·품질 직결."]'::jsonb, true),
  ('46095616-1902-58ea-9f10-3d1a92494d07'::uuid, '4장 · 5절 · 수장공사기타마감 · 걸레받이칸막이문', '방화셔터', '개구부를 화재 시 자동 폐쇄하는 셔터. 감지기 연동 — 피난과의 간섭(비상문 내장) 관리.', '[]'::jsonb, false),
  ('c67db60a-4704-5ded-8e9a-a30c8ef445ed'::uuid, '4장 · 5절 · 수장공사기타마감 · 층간소음바닥충격음', '층간소음 (중량 · 경량충격음)', '위층 바닥 충격이 아래층에 전달되는 소음. 경량충격음(가벼운 물건 낙하 — 태핑머신 측정)과 중량충격음(아이 뛰는 소리 — 뱅머신·임팩트볼)으로 구분.', '["성능 기준·사후확인제 등 규제 강화 흐름. ※기준 확인."]'::jsonb, true),
  ('ca36092d-ed7a-5811-b99c-96580f2fbbdf'::uuid, '4장 · 5절 · 수장공사기타마감 · 층간소음바닥충격음', '완충재', '슬래브 위에 까는 탄성층(EPS·EVA 등). 충격 에너지를 흡수해 구조체 전달 저감.', '[]'::jsonb, false),
  ('7a578b40-48e0-5184-9738-9d3fa9ecfd9d'::uuid, '4장 · 5절 · 수장공사기타마감 · 층간소음바닥충격음', '뜬바닥구조', '슬래브·완충재·경량기포콘크리트·마감 모르타르로 바닥을 구조체에서 띄운 구성. 층간소음 대책의 표준 단면.', '["비교·암기 — ''바닥을 구조체에서 분리해 띄운다'' — 뜬바닥+완충재+슬래브 두께 확보가 3대 대책."]'::jsonb, false),
  ('0776ba51-be25-5ba3-8525-b2760f882577'::uuid, '4장 · 5절 · 수장공사기타마감 · 층간소음바닥충격음', '이중벽 · 벽체 차음', '벽 앞에 공기층을 두고 별도 벽(석고보드+스터드)을 세운 구성. 벽 전달 소음·결로 대응.', '[]'::jsonb, false),
  ('31cf83d0-39c2-526e-8580-f2170afeb6a0'::uuid, '4장 · 5절 · 수장공사기타마감 · 층간소음바닥충격음', '흡음재 (다공질 · 판진동 · 천공판)', '다공질(글라스울 — 중고음 흡수), 판진동(합판 등 — 저음), 천공판(공명 — 특정 주파수), 흡음 원리 3형제.', '[]'::jsonb, false),
  ('3fa2a009-2b86-5f96-b6cd-011b328f13be'::uuid, '4장 · 5절 · 수장공사기타마감 · 층간소음바닥충격음', '차음과 흡음의 구분', '차음: 소리를 차단(질량·기밀 — 무겁고 빈틈 없이). 흡음: 소리를 흡수해 반사·잔향을 줄임(다공질).', '["비교·암기 — ''차음은 막고, 흡음은 먹는다'' — 목적이 다르므로 재료도 다름(무거운 벽 vs 폭신한 판). 최다 출제 비교."]'::jsonb, false),
  ('55358db1-4112-5813-8e01-670c3128228c'::uuid, '4장 · 6절 · 합성수지 · 수지의2대분류', '열가소성수지', '열을 가하면 다시 물러져 재성형 가능한 수지(사슬 구조).', '["PVC·PE·PP·아크릴·폴리카보네이트 — ''데우면 다시 말랑''."]'::jsonb, false),
  ('f6ab41d3-6a89-594a-9456-cca7b17ff341'::uuid, '4장 · 6절 · 합성수지 · 수지의2대분류', '열경화성수지', '한 번 굳으면 열을 가해도 다시 물러지지 않는 수지(그물 구조).', '["페놀·에폭시·멜라민·폴리에스터·우레탄·실리콘 — ''한 번 굳으면 끝''.", "비교·암기 — 열가소성(재성형 가능·사슬) ↔ 열경화성(불가·그물) — 재료 시험 최다 출제 분류. 접착제·도료는 대부분 열경화성 계열."]'::jsonb, false),
  ('4ba7eaaf-806d-550f-8dbe-8fdf8182a1cf'::uuid, '4장 · 6절 · 합성수지 · 열가소성수지들', '염화비닐수지 (PVC)', '가장 널리 쓰이는 범용 수지 — 새시·바닥재·배관·시트. 내약품·경제성, 열에 약함.', '[]'::jsonb, false),
